/**
 * Room image generation API — the live wiring for the Universal JSON
 * Architecture's step 6 (revamp plan). Assembles this room's final prompt
 * deterministically (prompt-builder.ts, from the cached DesignSpecification)
 * and generates it via the AI provider layer (provider.ts's generateImage),
 * the same shape used for video generation so this can move to an async job
 * later without a call-site rewrite.
 *
 *   POST /api/generate-room-image  { projectId, universalInput, room, designSpec }
 *     → { imageUrl, key, prompt }
 *
 * Generated bytes are stored under "renders/<projectId>/..." via the same
 * storage layer (and served back through) GET /api/render?key=..., so both
 * generation paths share one image-serving route.
 */

import { randomUUID } from "node:crypto";
import { buildRoomPrompt } from "@/lib/ai/prompting/prompt-builder";
import type { DesignSpecification, UniversalInput, UniversalInputRoom } from "@/lib/ai/prompting/types";
import { generateImage } from "@/lib/ai/provider";
import { ProviderError, toErrorResponse } from "@/lib/ai/errors";
import { getObject, putObject } from "@/lib/pipeline/storage";
import { recordGeneration } from "@/lib/supabase/generations";
import { assertAllowed } from "@/lib/api-guard";
import { requireOwnedProject } from "@/lib/supabase/projects";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 120;

// Matches build-universal-input.ts's NOTES_MAX_LEN for the global Additional
// Requirements field — this is the per-generation "Generate More" note, a
// separate field that isn't validated by buildUniversalInput.
const NOTES_MAX_LEN = 500;

interface Body {
  projectId?: string;
  universalInput?: UniversalInput;
  room?: UniversalInputRoom;
  designSpec?: DesignSpecification;
  /** Room.greyboxKey — this room's rendered perspective reference, if the user placed it in the Plan Editor. */
  greyboxKey?: string;
}

async function loadGreyboxDataUri(key: string): Promise<string> {
  const bytes = await getObject(key);
  return `data:image/png;base64,${bytes.toString("base64")}`;
}

export async function POST(request: Request) {
  // Image generation is one paid provider call per request.
  const guard = await assertAllowed(request, {
    rateLimit: { key: "generate-room-image", limit: 8, windowMs: 60_000 },
    checkUsage: true,
  });
  if (guard instanceof Response) return guard;

  let body: Body;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { projectId, universalInput, room, designSpec, greyboxKey } = body;
  if (!projectId || !universalInput || !room || !designSpec) {
    return Response.json(
      { error: "projectId, universalInput, room and designSpec are required" },
      { status: 400 },
    );
  }
  if (room.additional_notes && room.additional_notes.length > NOTES_MAX_LEN) {
    const err = new ProviderError(
      "ValidationError",
      `additional notes exceed ${NOTES_MAX_LEN} characters`,
    );
    return Response.json({ error: err.message, category: err.category }, { status: 400 });
  }

  // Without this check, an authenticated caller could pass ANY other
  // project's id (or a made-up one) and have a billed image generated and
  // stored under it, plus a `generations` row recorded against it — a
  // cross-tenant data leak.
  const owned = await requireOwnedProject(guard.id, projectId);
  if (owned instanceof Response) return owned;

  try {
    const prompt = await buildRoomPrompt(universalInput, room, designSpec, { hasGreybox: !!greyboxKey });
    const referenceImages = greyboxKey ? [await loadGreyboxDataUri(greyboxKey)] : undefined;
    const referenceImageUrls = greyboxKey ? [`/api/render?key=${encodeURIComponent(greyboxKey)}`] : undefined;
    const image = await generateImage(prompt, { projectId, userId: guard.id }, { referenceImages, referenceImageUrls });
    const ext = image.contentType === "image/jpeg" ? "jpg" : "png";
    const key = `renders/${projectId}/${randomUUID()}.${ext}`;
    await putObject(key, image.bytes, image.contentType);
    const imageUrl = `/api/render?key=${encodeURIComponent(key)}`;
    // Awaited (was fire-and-forget `void`): /api/render's ownership check now
    // reads this row to authorize a just-generated image immediately, instead
    // of waiting on the client's debounced project-snapshot sync (found via a
    // direct user report of freshly-generated images intermittently failing
    // to load). recordGeneration itself never throws (best-effort insert),
    // so awaiting it only adds one DB round-trip, no new failure mode.
    await recordGeneration({ projectId, userId: guard.id, roomKey: room.name, type: "image", storageUrl: imageUrl });
    return Response.json({ imageUrl, key, prompt });
  } catch (e) {
    const { status, body } = toErrorResponse(e, "Room image generation");
    return Response.json(body, { status });
  }
}
